"""Splitting money between parties."""

from collections.abc import Sequence


def allocate(total: int, weights: Sequence[int], caps: Sequence[int] | None = None) -> list[int]:
    """Split `total` cents in proportion to `weights`. See README.md for the rules."""
    if total < 0:
        raise ValueError("total must not be negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(weight < 0 for weight in weights):
        raise ValueError("weights must not contain a negative entry")
    if sum(weights) == 0:
        raise ValueError("weights must not add up to zero")

    if caps is not None:
        if len(caps) != len(weights):
            raise ValueError("caps must have one entry per weight")
        if any(cap < 0 for cap in caps):
            raise ValueError("caps must not contain a negative entry")
        if sum(cap for weight, cap in zip(weights, caps) if weight > 0) < total:
            raise ValueError("the parties with a positive weight cannot hold the total")

    result = [0] * len(weights)
    remaining = total
    active = list(range(len(weights)))

    while remaining > 0 and active:
        weight_sum = sum(weights[i] for i in active)
        numerators = {i: remaining * weights[i] for i in active}
        shares = {i: numerators[i] // weight_sum for i in active}
        leftover = remaining - sum(shares.values())
        order = sorted(active, key=lambda i: (-(numerators[i] % weight_sum), i))
        for i in order[:leftover]:
            shares[i] += 1

        over = [i for i in active if caps is not None and shares[i] > caps[i]]
        if not over:
            for i, share in shares.items():
                result[i] = share
            break

        for i in over:
            result[i] = caps[i]
            remaining -= caps[i]
        capped = set(over)
        active = [i for i in active if i not in capped]

    return result
